function shoppingUnit(category,item){const text=`${category||''} ${item||''}`.toLowerCase();if(/milk|juice|water|soda|beverage|detergent|cleaner|oil/.test(text))return 'gallon';if(/beef|chicken|steak|bacon|fish|meat|seafood|cheese/.test(text))return 'pound';if(/egg/.test(text))return 'dozen';if(/bread|bagel|tortilla|paper towel|toilet paper|napkin|tissue|diaper|wipe|trash bag|sponge/.test(text))return 'package';if(/apple|banana|avocado|tomato|berry|produce|snack|chip|cracker|nut|bar/.test(text))return 'individual';return 'individual';}
function shoppingForm(propertyId){const categoryOptions='<option value="">Choose a category</option>'+shoppingCategories.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('');const fields=select('category','1. Category',categoryOptions)+'<div id="shoppingItemSlot"></div><div id="shoppingVariantSlot"></div><div id="shoppingBrandSlot"></div>'+input('quantity','Quantity','number','1')+select('quantityUnit','Unit',shoppingUnitOptions('individual'))+textarea('notes','Preferences or placement');dialog('Add preferred item',fields,'Save',async(b)=>{if(!b.category)throw Error('Choose a category first.');const baseItem=b.itemChoice==='Other'?b.customItem:b.itemChoice;const variant=b.variantChoice==='Other'?b.customVariant:b.variantChoice;const item=[baseItem,variant&&variant!=='Other'?variant:''].filter(Boolean).join(' - ');const brand=b.brandChoice==='Other'?b.customBrand:b.brandChoice;if(!item?.trim())throw Error('Choose an item or enter a custom item.');if(!brand?.trim())throw Error('Choose a brand or enter a custom brand.');const notes=[brand?`Brand: ${brand}`:'',b.notes].filter(Boolean).join('\n');await api('shopping',{propertyId,name:item.trim(),quantity:`${b.quantity||1} ${b.quantityUnit||'individual'}`,category:b.category||'Other',notes});});const updateBrands=()=>{const category=$('f-category').value,item=$('f-itemChoice').value,variant=$('f-variantChoice')?.value;const items=shoppingCatalog[category]||{'Other':['Other']};const brands=[...(items[item]||['Other']),...(retailerBrands[category]||[])].filter((b,i,a)=>a.indexOf(b)===i);$('shoppingBrandSlot').innerHTML=select('brandChoice','4. Brand','<option value="">Choose a brand</option>'+brands.map(b=>`<option value="${esc(b)}">${esc(b)}</option>`).join(''))+'<div id="shoppingCustomBrand"></div>';$('f-brandChoice').onchange=()=>{$('shoppingCustomBrand').innerHTML=$('f-brandChoice').value==='Other'?input('customBrand','Custom brand'):'';};const labelItem=[item,variant&&variant!=='Other'?variant:''].filter(Boolean).join(' ');if($('f-quantityUnit'))$('f-quantityUnit').value=shoppingUnit(category,labelItem);};const update=()=>{const category=$('f-category').value;const items=shoppingCatalog[category]||{'Other':['Other']};const itemOptions='<option value="">Choose an item</option>'+Object.keys(items).map(item=>`<option value="${esc(item)}">${esc(item)}</option>`).join('');$('shoppingItemSlot').innerHTML=select('itemChoice','2. Item',itemOptions)+'<div id="shoppingCustomItem"></div>';const item=$('f-itemChoice');const variants=shoppingVariants[category]?.[item.value];$('shoppingVariantSlot').innerHTML=variants?select('variantChoice','3. Type',variants.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join(''))+'<div id="shoppingCustomVariant"></div>':'';if(variants){$('f-variantChoice').onchange=()=>{$('shoppingCustomVariant').innerHTML=$('f-variantChoice').value==='Other'?input('customVariant','Custom type'):'';updateBrands();};}$('shoppingBrandSlot').innerHTML='';item.onchange=()=>{$('shoppingCustomItem').innerHTML=item.value==='Other'?input('customItem','Custom item name'):'';const next=shoppingVariants[category]?.[item.value];$('shoppingVariantSlot').innerHTML=next?select('variantChoice','3. Type',next.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join(''))+'<div id="shoppingCustomVariant"></div>':'';if(next){$('f-variantChoice').onchange=()=>{$('shoppingCustomVariant').innerHTML=$('f-variantChoice').value==='Other'?input('customVariant','Custom type'):'';updateBrands();};}$('shoppingBrandSlot').innerHTML='';updateBrands();};if(item.value)updateBrands();};$('f-category').onchange=update;update();}

const option=(rows,value='id',name='name',selected='')=>rows.map(r=>`<option value="${esc(r[value])}" ${r[value]===selected?'selected':''}>${esc(r[name])}</option>`).join('');
const input=(name,title,type='text',value='',required=true)=>`<div class="field"><label for="f-${name}">${esc(title)}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='number'?'step="0.01" min="0.01"':''} ${type==='password'?'minlength="12" autocomplete="new-password"':''}></div>`;
const select=(name,title,options)=>`<div class="field"><label for="f-${name}">${esc(title)}</label><select id="f-${name}" name="${name}">${options}</select></div>`;
const textarea=(name,title,value='')=>`<div class="field full"><label for="f-${name}">${esc(title)}</label><textarea id="f-${name}" name="${name}">${esc(value)}</textarea></div>`;
function familyForm(c={}){return createForm(c.id?'Edit client family':'Add client family',input('name','Family name','text',c.name||'')+input('email','Primary email','email',c.email||'',false)+input('phone','Phone','tel',c.phone||'',false),c.id?'clients/update':'clients',{id:c.id||undefined},async()=>{await load();});}
function requestPriorityBadge(priority){const value=String(priority||'normal').toLowerCase();return badge(value==='high'||value==='urgent'?'Urgent':value);}
const roomTypes=[['living-room','Living room'],['family-room','Family room'],['dining-room','Dining room'],['kitchen','Kitchen'],['office','Office'],['laundry-room','Laundry room'],['garage','Garage'],['patio','Patio / outdoor area'],['pool-house','Pool house'],['guest-house','Guest house']];
const clientRoomProfile=p=>{try{return typeof p.room_profile==='string'?JSON.parse(p.room_profile||'{}'):(p.room_profile||{});}catch{return {};}};
const roomCount=(name,title,value=0)=>`<div class="field"><label for="f-${name}">${esc(title)}</label><input id="f-${name}" name="${name}" type="number" min="0" step="1" value="${esc(value)}"></div>`;
const customRoomTypes=['Bedroom','Full bathroom','Half bathroom','Kitchen','Dining room','Living room','Family room','Office','Library','Gym','Theater','Wine cellar','Laundry room','Garage','Patio / outdoor area','Pool house','Guest house','Staff quarters','Storage','Other'];
const roomProfileForm=(p={})=>{const rooms=clientRoomProfile(p).rooms||[];return `<fieldset class="room-profile" data-client="${esc(p.client_id||'')}"><legend>Residence rooms and spaces</legend><p class="muted">Add each room separately, including guest suites and additional kitchens. Give each space its own name, floor, assignment and preparation notes.</p><div id="custom-rooms">${rooms.map(roomEditor).join('')}</div><button type="button" id="add-custom-room">Add room or space</button><input type="hidden" name="roomProfile" id="f-roomProfile"></fieldset>`;};
function roomEditor(r={}){const key=r.key||crypto.randomUUID(),type=r.type||(/bedroom/.test(key)?'Bedroom':/bathroom/.test(key)?(key.includes('half')?'Half bathroom':'Full bathroom'):roomTypes.find(t=>t[0]===key)?.[1]||'Other');return `<section class="custom-room" data-key="${esc(key)}"><div class="custom-room-grid"><label>Room type<select data-room="type">${[...new Set([...customRoomTypes,type])].map(t=>`<option ${t===type?'selected':''}>${esc(t)}</option>`).join('')}</select></label><label>Room name<input data-room="name" value="${esc(r.name||'')}" placeholder="Primary bedroom, east guest suite…" required></label><label>Floor / level<input data-room="floor" value="${esc(r.floor||'')}" placeholder="Ground floor, second floor, guest house…"></label><label>Assigned to<select data-room="assignment" data-saved="${esc(r.assignment||'')}"><option value="">Unassigned</option></select></label><label class="room-other">Person or guest name<input data-room="assignedName" value="${esc(r.assignedName||'')}" placeholder="Name or other assignment"></label><label class="room-notes">Room notes<textarea data-room="notes" placeholder="Bedding preferences, setup instructions, special features…">${esc(r.notes||'')}</textarea></label></div><button type="button" data-remove-room>Remove room</button></section>`;}
function syncRoomProfile(){const field=$('f-roomProfile');if(!field)return;const rooms=[...document.querySelectorAll('.custom-room')].map(el=>{const read=k=>el.querySelector(`[data-room="${k}"]`).value;const assignment=read('assignment');return {key:el.dataset.key,type:read('type'),name:read('name'),floor:read('floor'),assignment,assignedName:assignment.startsWith('member:')?el.querySelector('[data-room="assignment"]').selectedOptions[0].textContent:(['guest','other'].includes(assignment)?read('assignedName'):''),notes:read('notes')};});field.value=JSON.stringify({rooms,bedrooms:rooms.filter(r=>r.type==='Bedroom').length,fullBathrooms:rooms.filter(r=>r.type==='Full bathroom').length,halfBathrooms:rooms.filter(r=>r.type==='Half bathroom').length});}
function roomAssignments(){const box=document.querySelector('.room-profile');if(!box)return;const clientId=$('f-clientId')?.value||box.dataset.client;const c=data.clients.find(c=>c.id===clientId);let profile={};try{profile=JSON.parse(c?.profile||'{}');}catch{}const members=profile.members||[];box.querySelectorAll('[data-room="assignment"]').forEach(select=>{const selected=select.dataset.saved??select.value;select.innerHTML='<option value="">Unassigned</option>'+members.map(m=>`<option value="member:${esc(m.id)}">${esc([m.firstName,m.lastName].filter(Boolean).join(' '))}</option>`).join('')+'<option value="guest">Guest</option><option value="other">Other</option>';if(selected.startsWith('member:')&&!members.some(m=>'member:'+m.id===selected))select.add(new Option('Previously assigned person',selected));select.value=selected;delete select.dataset.saved;});syncRoomProfile();}
function wireRooms(){const box=document.querySelector('.room-profile');if(!box)return;roomAssignments();box.addEventListener('input',syncRoomProfile);box.addEventListener('change',syncRoomProfile);$('add-custom-room').onclick=()=>{$('custom-rooms').insertAdjacentHTML('beforeend',roomEditor({type:'Bedroom'}));roomAssignments();};box.addEventListener('click',e=>{if(e.target.hasAttribute('data-remove-room')){e.target.closest('.custom-room').remove();syncRoomProfile();}});$('f-clientId')?.addEventListener('change',()=>{box.querySelectorAll('[data-room="assignment"]').forEach(el=>el.value='');roomAssignments();});}
function roomDetails(r){return `<div><strong>${esc(r.name)}</strong><div class="muted">${esc([r.type,r.floor,r.assignedName].filter(Boolean).join(' · '))}</div>${r.notes?`<p class="pre">${esc(r.notes)}</p>`:''}</div>`;}
const addressForm=(p={})=>`<fieldset class="address-fields"><legend>Property address</legend><div class="field full"><label for="f-addressSearch">Find address</label><input id="f-addressSearch" autocomplete="street-address" placeholder="Start typing an address"><div id="addressSuggestions" class="address-suggestions"></div></div>${p.address&&!p.street_address?`<p class="muted address-previous">Previously saved address: ${esc(p.address)}</p>`:''}<div class="field full"><label for="f-streetAddress">Street address</label><input id="f-streetAddress" name="streetAddress" autocomplete="address-line1" placeholder="123 Ocean Drive" value="${esc(p.street_address||'')}" required></div><div class="field full"><label for="f-addressLine2">Apartment, suite or unit <span class="muted">(optional)</span></label><input id="f-addressLine2" name="addressLine2" autocomplete="address-line2" placeholder="Unit 4B" value="${esc(p.address_line2||'')}"></div><div class="field"><label for="f-city">City</label><input id="f-city" name="city" autocomplete="address-level2" value="${esc(p.city||'')}" required></div><div class="field"><label for="f-state">State / province</label><input id="f-state" name="state" autocomplete="address-level1" placeholder="FL" value="${esc(p.state||'')}" required></div><div class="field"><label for="f-postalCode">ZIP / postal code</label><input id="f-postalCode" name="postalCode" autocomplete="postal-code" placeholder="33480" value="${esc(p.postal_code||'')}" required></div><div class="field"><label for="f-country">Country</label><input id="f-country" name="country" autocomplete="country-name" value="${esc(p.country||'United States')}" required></div></fieldset>`;
function toast(message){$('toast').textContent=message;$('toast').hidden=false;setTimeout(()=>$('toast').hidden=true,5000);}
async function api(path,payload){const response=await fetch('/api/'+path,payload===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const result=await response.json();if(!response.ok)throw Object.assign(new Error(result.error||'Request failed.'),{status:response.status});return result;}
let loadPromise=null,lastLoadAt=0;async function load(){if(loadPromise)return loadPromise;const now=Date.now();if(now-lastLoadAt<1500&&data){render();return data;}loadPromise=(async()=>{const next=await api('data');const tasks=[api('messages'),api('operations'),api('security')];if(next.user.role==='admin')tasks.push(api('subscription'),api('billing/status'));if(next.user.platformOwner)tasks.push(api('billing-sandbox/status'),api('platform/storage'),api('platform/companies'));if(['admin','employee'].includes(next.user.role))tasks.push(api('staff/data'));const results=await Promise.all(tasks);let i=0;next.messaging=results[i++];next.operations=results[i++];next.security=results[i++];if(next.user.role==='admin'){next.subscription=results[i++];next.billing=results[i++];}if(next.user.platformOwner){next.stripeSandbox=results[i++];next.platformStorage=results[i++].companies;platformCompanies=results[i++].companies;}if(['admin','employee'].includes(next.user.role))next.staff=results[i++];data=next;lastLoadAt=Date.now();render();return data;})().finally(()=>{loadPromise=null;});return loadPromise;}
function dialog(title,fields,submit,onSubmit){$('modalBody').innerHTML=`<h2>${esc(title)}</h2><div id="formError" class="error" hidden></div><form id="actionForm" class="form">${fields}<div class="dialog-footer">${btn('Cancel','close')}<button class="primary" type="submit">${esc(submit)}</button></div></form>`;$('actionForm').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{syncRoomProfile();const values=Object.fromEntries(new FormData(e.target));await onSubmit(values,e.target);$('modal').close();if(!securitySignedOut)await load();}catch(error){$('formError').hidden=false;$('formError').textContent=error.message;}finally{button.disabled=false;}};$('modal').showModal();}
function auth(configured,invitation){
  let loginMode=configured&&!invitation;
  let mode=new URLSearchParams(location.search).has('reset')?'reset':'login';
  const resetToken=new URLSearchParams(location.search).get('reset')||'';
  const draw=()=>{
    const reset=mode==='reset', forgot=mode==='forgot';
    const fields=reset?input('token','Reset token','hidden',resetToken,false)+input('newPassword','New password','password')+input('confirmPassword','Confirm new password','password'):forgot?input('email','Email','email'):(!loginMode&&!invitation?input('company','Company name')+logoField()+input('setupKey','Setup key from Render','password','',false):'')+(!loginMode&&invitation?input('name','Your name'):'')+(!invitation?input('email','Email','email'):'')+input('password','Password','password')+(!invitation?input('code','Authenticator or recovery code (if enabled)','text','',false):'');
    const title=reset?'Set a new password':forgot?'Forgot your password?':invitation?'Create your account':loginMode?'Sign in to EstateAegis':'Set up your company';
    $('app').innerHTML=`<div class="auth"><section class="auth-intro"><video class="auth-video" autoplay muted loop playsinline preload="metadata" poster="/waterfront.jpg" aria-hidden="true"><source src="/waterfront.mp4" type="video/mp4"></video><div class="brand"><img class="ea-brand-icon" src="/ea-shield.png" alt="" width="40" height="40">EstateAegis</div><h1>Your residences.<br>Our team.<br>One place.</h1><p>Manage property care, prepare for arrivals, and keep every service and inspection connected to the right residence.</p></section><section class="auth-form"><div><div class="eyebrow">${reset||forgot?'Password recovery':invitation?'Your invitation':loginMode?'Welcome back':'Company setup'}</div><h2>${title}</h2><p class="muted">${reset?'Choose a new password for your account.':forgot?'Enter your email and we will send a secure reset link if an account matches.':loginMode?'Use the email and password for your account.':invitation?'Choose your name and a password for your individual account.':'Create the first administrator account. Your workspace starts empty, ready for your real records.'}</p><div id="authError" class="error" hidden></div><form id="authForm">${fields}<button class="primary" type="submit">${reset?'Reset password':forgot?'Send reset link':invitation?'Accept invitation':loginMode?'Sign in':'Create company'}</button></form>${reset||forgot?'<p class="footer-note"><button type="button" class="link-button" data-auth-mode="login">Back to sign in</button></p>':(!invitation?`<p class="footer-note">${loginMode?'Need to create the first workspace? ': 'Already have an account? '}<button type="button" class="link-button" data-auth-mode="${loginMode?'setup':'login'}">${loginMode?'Set up a new company':'Log in to an existing account'}</button>${loginMode?' · <button type="button" class="link-button" data-forgot>Forgot password?</button>':''}</p>`:`<p class="footer-note">Use a password with at least 12 characters. This invitation expires after 48 hours.</p>`)}</div></section></div>`;
    $('authForm').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const payload=Object.fromEntries(new FormData(e.target));if(e.target.querySelector('[name=companyLogo]'))payload.logoData=await readCompanyLogo(e.target);if(invitation)payload.token=invitation;if(reset){await api('password-reset',payload);mode='login';history.replaceState(null,'','/login');draw();$('authError').textContent='Your password was reset. You can now sign in.';$('authError').hidden=false;}else if(forgot){await api('password-reset/request',payload);$('authError').textContent='If an account matches, we’ll send a reset link.';$('authError').hidden=false;e.target.reset();}else{await api(invitation?'accept-invite':loginMode?'login':'setup',payload);history.replaceState(null,'','/');await load();}}catch(error){$('authError').textContent=error.message;$('authError').hidden=false;}finally{e.submitter.disabled=false;}};
    const modeButton=document.querySelector('[data-auth-mode]');if(modeButton)modeButton.onclick=()=>{const next=modeButton.dataset.authMode;mode=next==='login'?'login':next;loginMode=next==='login';draw();};const forgotButton=document.querySelector('[data-forgot]');if(forgotButton)forgotButton.onclick=()=>{mode='forgot';draw();};
  };draw();
}
function companyLogo(){return data&&data.workspaceLogo?`<img class="company-logo" src="${esc(data.workspaceLogo)}" alt="">`:"";}
function logoField(){return `<div class="field"><label for="f-companyLogo">Company logo (optional)</label><input id="f-companyLogo" name="companyLogo" type="file" accept="image/png,image/jpeg,image/webp"></div>`;}
async function readCompanyLogo(form){const file=form?.querySelector("[name=companyLogo]")?.files?.[0];if(!file)return "";if(file.size>2*1024*1024)throw Error("Logo must be smaller than 2 MB.");return await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(",")[1]||"");reader.onerror=reject;reader.readAsDataURL(file);});}
function fitWorkspaceName(){}
function initializeNavigation(){}
function recordNavigation(){}
function sidebarStorageKey(){return 'estateos-sidebar-groups:'+data.user.id;}
function groupedNavigation(nav){
 const groups=[['residences','Residences & Clients',['properties','clients','arrivals','shopping']],['operations','Daily Operations',['work','requests','inspections','calendar','routes']],['people','Staff & Vendors',['staff','staff-schedules','vendors','users']],['records','Property Records',['assets','maintenance','documents']],['administration','Administration',['platform','workspace','billing','audit']],['account','Account',['profile','notifications']]];
 let saved={};try{saved=JSON.parse(localStorage.getItem(sidebarStorageKey())||'{}')||{};}catch{}
 const active=page==='property'?'properties':page==='inspection'?'inspections':page==='asset-inspection'?'assets':page;
 const item=([id,title])=>`<button data-action="navigate" data-id="${id}" class="nav-item ${active===id?'active':''}" ${active===id?'aria-current="page"':''}>${esc(title)}</button>`;
 const direct=nav.filter(n=>['dashboard','messages'].includes(n[0])).map(item).join('');
 const grouped=groups.map(([id,title,ids])=>{const entries=ids.map(key=>nav.find(n=>n[0]===key)).filter(Boolean);if(!entries.length)return '';const open=entries.some(n=>n[0]===active)||saved[id]===true;return `<details class="nav-group" data-nav-group="${id}" ${open?'open':''}><summary>${esc(title)}<span class="nav-chevron" aria-hidden="true">›</span></summary><div class="nav-group-items">${entries.map(item).join('')}</div></details>`;}).join('');
 return `<nav aria-label="Main navigation" class="grouped-nav">${direct}${grouped}</nav>`;
}
document.addEventListener('toggle',event=>{const el=event.target;if(!el.matches?.('details[data-nav-group]')||!el.isConnected||!data?.user)return;try{const key=sidebarStorageKey();const saved=JSON.parse(localStorage.getItem(key)||'{}')||{};saved[el.dataset.navGroup]=el.open;localStorage.setItem(key,JSON.stringify(saved));}catch{}},true);
function familyMemberActions(p,m){
 if(data.user.role!=='admin')return '';
 const email=String(m.email||'').trim().toLowerCase();
 const account=(data.users||[]).find(u=>u.role==='client'&&u.client_id===p.client_id&&((m.accessUserIds||[]).includes(u.id)||(email&&String(u.email||'').toLowerCase()===email)));
 const pending=(data.invitations||[]).filter(i=>i.clientId===p.client_id&&i.role==='client'&&i.status==='pending'&&((m.invitationIds||[]).includes(i.id)||(email&&String(i.email||'').toLowerCase()===email)));
 const action=(text,name)=>`<button data-action="${name}" data-id="${esc(m.id)}" data-property-id="${esc(p.id)}">${text}</button>`;
 return `<div><div class="muted">${account?(account.active?'Client access active':'Client access suspended'):pending.length?'Invitation pending':email?'Not invited':'Add an email to invite'}</div><div class="actions">${action(email?'Edit email':'Add email','family-member-email')}${!account&&!pending.length&&email?action('Send invite','family-send-invite'):''}${pending.map(i=>btn('Cancel invitation','cancel-invite',i.id)).join('')}${action('Remove','residence-member-delete')}</div></div>`;
}

function render(){initializeNavigation();const role=data.user.role;let nav=[['dashboard','Overview'],['messages','Messages'+(data.unreadMessages?' ('+data.unreadMessages+')':'')],['properties',role==='client'?'My residences':'Residences'],['work',role==='vendor'?'My jobs':'Work orders']];if(role==='client')nav.push(['shopping','Shopping list']);if(role!=='vendor')nav.push(['inspections','Inspection reports'],['requests','Service requests'],['arrivals','Arrival preparation'],['calendar','Calendar'],['documents','Documents']);if(isStaff())nav.push(['maintenance','Maintenance'],['assets','Assets'],['routes','Daily route']);if(data.user.platformOwner||role==='admin')nav.push(['platform','Platform Administration']);if(isStaff())nav.push(['staff-schedules','Staff schedules']);if(role==='admin')nav.push(['staff','Staff']);if(role==='admin')nav.push(['workspace','Company settings']);if(role==='admin')nav.push(['clients','Client families'],['vendors','Vendors'],['billing','Billing'],['users','Team & access'],['audit','Audit history']);if(['admin','client'].includes(role))nav.push(['approvals','Client approvals']);if(role==='admin')nav.push(['automation','Schedules & automation'],['email-activity','Email activity']);nav.push(['profile','My profile'],['notifications','Notifications']);if(!nav.some(n=>n[0]===page)&&page!=='property'&&page!=='inspection'&&page!=='asset-inspection')page='dashboard';recordNavigation();$('app').innerHTML=`<div class="shell"><aside id="sidebar"><div class="workspace-brand"><img class="workspace-brand-icon" src="/ea-shield.png" alt=""><strong title="${esc(data.company)}">${esc(data.company)}</strong></div>${groupedNavigation(nav)}${data.user.platformOwner?'<a href="/platform">Platform administration</a>':''}<div class="identity">${esc(data.user.name)}<small>${esc(label(role))}</small>${btn('Sign out','logout')}</div></aside><main><header class="topbar"><div class="mobile-navigation">${btn('Menu','menu')}${btn('Back','browser-back')}</div><input id="search" aria-label="Search current view" placeholder="Search residences, work and records…" value="${esc(search)}"><span class="company company-brand">${companyLogo()}<span>Powered by EstateAegis</span>${data.unreadMessages?`<span class="topbar-unread">${esc(data.unreadMessages)} unread</span>`:""}</span></header>${data.demo?'<div class="demo-banner" role="status">Private demo · expires '+esc(new Date(Number(data.demo.expires_at)).toLocaleDateString())+' · Emails and payments disabled. <a href="/demo-guide" target="_blank" rel="noopener">Watch quick start</a> '+(data.user.id===data.demo.admin_id?'<button type="button" id="resetPrivateDemo">Reset demo</button>':'')+'</div>':''}<div class="content" id="content">${view()}</div></main></div>`;fitWorkspaceName();restoreDraft();$('search').addEventListener('input',e=>{search=e.target.value; $('content').innerHTML=search?globalSearch():view();});}
function filtered(rows){const q=search.toLowerCase();return rows.filter(r=>!q||Object.values(r).some(v=>typeof v==='string'&&v.toLowerCase().includes(q)));}
function upcomingInspections(reference=new Date()){const day=new Date(reference);day.setHours(0,0,0,0);const end=new Date(day);end.setDate(end.getDate()+3);return data.inspections.filter(i=>{if(!i.next_due)return false;const due=new Date(i.next_due.slice(0,10)+'T00:00:00');return due>=day&&due<=end;}).sort((a,b)=>a.next_due.localeCompare(b.next_due));}
function head(title,subtitle='',action=''){return `<div class="head"><div><div class="eyebrow">${esc(data.company)}</div><h1>${esc(title)}</h1>${subtitle?`<div class="muted">${esc(subtitle)}</div>`:''}</div>${action}</div>`;}
function onboardingPanel(){if(data.user.role!=='admin')return '';const hasRooms=data.properties?.some(p=>{try{return JSON.parse(p.room_profile||'[]').length>0;}catch{return false;}});const steps=[['Create a client family',data.clients?.length>0,'clients'],['Add the family residence',data.properties?.length>0,'properties'],['Add rooms and spaces',hasRooms,'properties'],['Set up your company details',Boolean(data.company),'workspace'],['Invite your team',data.users?.some(u=>u.role!=='admin'),'users'],['Run your first inspection',data.inspections?.length>0,'inspections'],['Create a work order',data.work?.length>0,'work']];const done=steps.filter(s=>s[1]).length;if(done===steps.length)return '';return '<details class="panel onboarding-panel collapsible-section"><summary class="head"><div class="head"><div><div class="eyebrow">GETTING STARTED</div><h2>Build your workspace step by step</h2><p class="muted">Complete these essentials before inviting clients into a live workflow.</p></div><span class="badge">'+done+'/'+steps.length+' complete</span></summary>'+steps.map(s=>'<div class="row"><div><strong>'+(s[1]?'✓ ':'')+esc(s[0])+'</strong><div class="muted">'+(s[1]?'Complete':'Recommended next step')+'</div></div>'+(s[1]?'':btn('Open','navigate',s[2]))+'</div>').join('')+'</details>';}
function assignmentSummary(){return "";}
function dashboardTileGroups(){const groups=[['Residences & Arrivals', [['Residences',data.properties?.length||0,'properties'],['Upcoming arrivals',data.arrivals?.length||0,'arrivals'],['Submitted arrivals',data.arrivals?.length||0,'arrivals']] ],['Inspections & Service',[['Inspection reports',data.inspections?.length||0,'inspections'],['Upcoming inspections',0,'inspections-upcoming'],['Work orders',data.work?.length||0,'work'],['Service requests',data.requests?.length||0,'requests']]]];return groups.map(g=>'<section class=\"dashboard-group\"><h2>'+esc(g[0])+'</h2><div class=\"dashboard-tiles\">'+g[1].map(i=>'<button class=\"dashboard-tile\" data-action=\"navigate\" data-id=\"'+esc(i[2])+ '\"><span>'+esc(i[0])+'</span><strong>'+i[1]+'</strong><small>View details →</small></button>').join('')+'</div></section>').join('');}
function scheduleView(){return head('Staff schedules','Review staff assignments and upcoming work.',btn('Back','browser-back'))+'<div class="panel">'+workRows(data.work||[])+'</div>';}
function staffAction(name,key){if(name==='staff-schedule')return dialog('Staff schedule','<p class="muted">Schedule details can be managed from assigned work orders.</p>'+btn('Back','browser-back'),'Close',async()=>{});return false;}
function staffView(){const users=(data.users||[]).filter(u=>u.role!=='client');return head('Staff & vendors','Manage team access and assignments.',btn('Add staff member','new-invite','',true))+'<div class="panel">'+users.map(u=>'<div class="row"><div><strong>'+esc(u.name||u.email)+'</strong><div class="muted">'+esc(u.email||'')+' · '+esc(label(u.role))+'</div></div>'+badge(u.active===false?'inactive':'active')+'</div>').join('')+('</div>');}
function messagesView(){
 const m=data.messaging||{threads:[],people:[]};
 if(activeMessageThread&&messageDetail){
  const t=messageDetail.thread;
  return head(t.subject||'Conversation','Messages',btn('Back to messages','message-back'))+`
   <div class="panel message-detail">
    <div class="message-detail-head"><div><p class="eyebrow">${t.kind==='announcement'?'COMPANY-WIDE':'DIRECT MESSAGE'}</p><h2>${esc(t.subject)}</h2></div><div class="actions">${messageDetail.hasOlder?btn('Load older messages','message-older'):''}${btn('Refresh','message-refresh')}</div></div>
    <div class="message-list">${messageDetail.messages.map(x=>`<article class="message-bubble ${x.sender_id===data.user.id?'mine':''}"><strong>${esc(x.sender_name||'Unknown user')}</strong><p>${esc(x.body)}</p><time>${esc(new Date(x.created_at).toLocaleString())}</time></article>`).join('')||empty('No messages yet.')}</div>
    <div class="message-reply-actions">${btn('Reply','message-reply','',true)}</div>
   </div>`;
 }
 return head('Messages','Talk with staff, vendors, employees, clients, or the whole company.',btn('New message','message-new','',true))+
  `<div class="panel message-inbox">${m.threads.map(t=>`<button class="message-thread ${Number(t.unread)>0?'unread':''}" data-action="message-open" data-id="${esc(t.id)}"><span class="message-thread-copy"><strong>${esc(t.subject)}</strong><span>${esc((t.people||[]).map(p=>p.name).join(', '))}</span></span><span class="message-thread-meta">${Number(t.unread)>0?'<b>'+esc(t.unread)+' unread</b>':''}<small>${t.updated_at?esc(new Date(t.updated_at).toLocaleString()):''}</small></span></button>`).join('')||empty('No conversations yet. Start a message to someone on your team or send a company-wide update.')}</div>`;
}

function view(){
 if(page==='approvals')return approvalsView();if(page==='automation')return automationView();if(page==='email-activity')return deliveryView();if(page==='dashboard'&&data.user.role==='client')return clientHome();
 if(page==='messages')return messagesView();
 if(page==='platform'&&(data.user.platformOwner||data.user.role==='admin'))return platformView();
 if(page==='workspace'&&data.user.role==='admin')return head('Company settings','Settings for your company workspace.')+`<div class="panel"><div class="company-settings-brand">${companyLogo()}<h2>${esc(data.company)}</h2></div><p>Main administrator: ${esc(data.users.find(u=>u.id===data.primaryAdminId)?.name||'Not selected')}</p>${btn('Edit company branding and settings','workspace-settings')}</div>${stripeBillingPanel()}${subscriptionPanel(data.subscription)}`;
 if(page==='profile')return profileView();
 if(page==='clients'&&activeClient&&data.user.role==='admin'){const c=data.clients.find(c=>c.id===activeClient);if(c)return clientView(c);}

 if(page==='property')return residenceView();if(page==='inspection')return inspectionView();if(page==='asset-inspection')return assetInspectionView();
 if(page==='dashboard'){const open=data.work.filter(j=>j.status!=='completed');return head('Your estate overview','Property care, upcoming visits and recent updates.',data.user.role==='client'?btn('Plan my arrival','new-arrival','',true):'')+`${data.user.role==='client'?`<div class="residence-list">${data.properties.map(p=>residenceSummary(p)).join('')}</div>`:''}${data.subscription?.level?`<div class="notice"><strong>Company storage: ${data.subscription.percent.toFixed(1)}% used.</strong> ${btn('Review storage','navigate','workspace')}</div>`:''}${actionNeeded()}${onboardingPanel()}${dashboardTileGroups()}${!data.properties.length?`<div class="panel"><h2>${data.user.role==='admin'?'Begin with a client family':'Your workspace is ready'}</h2><p class="muted">${data.user.role==='admin'?'Add a family, then their residence. Invite your team and clients when their records are ready.':'Your administrator will assign residences or jobs to your account.'}</p>${data.user.role==='admin'?btn('Add client family','new-client','',true):''}</div>`:''}<div class="two"><details class="panel collapsible-panel"><summary>Work needing attention <span class="badge">${open.length}</span></summary>${workRows(open.slice(0,6))}</details><details class="panel collapsible-panel"><summary>Completed inspection reports <span class="badge">${data.inspections.filter(i=>i.status==='published').length}</span></summary>${inspectionRows(data.inspections.filter(i=>i.status==='published').slice(0,5))}</details></div>`;}
 if(page==='shopping')return head('Shopping list','Preferred items across your residences.')+data.properties.map(p=>`<div class="panel summary"><div class="head"><div><h2>${esc(p.name)}</h2><div class="muted">${esc(p.address||'Address not entered')}</div></div><div class="actions">${btn('Add item','new-shopping',p.id,true)}${btn('Plan arrival','new-arrival',p.id)}</div></div>${data.shopping.filter(i=>i.property_id===p.id).map(i=>`<div class="row"><div><strong>${esc(i.name)}</strong><div class="muted">${esc(i.category||'Other')} · ${esc(i.notes||'')}</div></div><div class="actions"><b>${esc(i.quantity)}</b>${btn('Edit','edit-shopping',i.id)}${btn('Remove','remove-shopping',i.id)}</div></div>`).join('')||empty('No preferred items saved for this residence yet.')}</div>`).join('')||empty('No residences are assigned to your account.');
 if(page==='properties')return head(data.user.role==='client'?'Your residences':'Residences','Each home, its records and its next visit.',data.user.role==='admin'?btn('Add residence','new-property','',true):'')+`<div class="residence-list">${filtered(data.properties).map(p=>residenceSummary(p)).join('')}</div>`+(!data.properties.length?empty('No residences assigned yet.'):'' )+(data.user.role==='admin'&&data.archivedProperties?.length?`<div class="panel summary"><h2>Archived residences</h2><p class="muted">Archived records are preserved and can be restored here.</p>${data.archivedProperties.map(p=>`<div class="row"><div><strong>${esc(p.name)}</strong><div class="muted">${esc(p.client_name||'')} · Archived ${esc(p.archived_at?.slice(0,10)||'')}</div></div>${btn('Restore residence','restore-property',p.id)}</div>`).join('')}</div>`:'');
 if(page==='clients')return head('Client families','Families and their residences.',btn('Add family','new-client','',true))+`<div class="panel">${filtered(data.clients).map(c=>`<div class="row"><div><strong>${esc(c.name)}</strong><div class="muted">${esc(c.email)} ${esc(c.phone)}</div></div><div class="actions">${badge(data.properties.filter(p=>p.client_id===c.id).length+' residences')}${btn('View family','client-open',c.id)}</div></div>`).join('')||empty('Add your first client family.')}</div>`;
 if(page==='vendors')return head('Vendor network','Create the vendor company, then invite its users.',btn('Add vendor','new-vendor','',true))+`<div class="panel">${filtered(data.vendors).map(v=>`<div class="row"><div><strong>${esc(v.name)}</strong><div class="muted">${esc(v.trade)} · ${esc(v.email)} · ${esc(v.phone)}</div></div></div>`).join('')||empty('No vendors yet.')}</div>`;
 if(page==='work')return head(data.user.role==='vendor'?'Your assigned jobs':'Work orders','Track work from assignment through verified completion.',isStaff()?btn('New work order','new-work','',true):'')+`<div class="panel">${workRows(filtered(data.work))}</div>`;
 if(page==='inspections'&&inspectionUpcomingOnly)return head('Upcoming inspections','Due within the next 3 days, soonest first.')+`<div class="panel">${upcomingInspections().filter((i,index,rows)=>rows.findIndex(x=>x.property_id===i.property_id)===index).map(i=>`<div class="row"><div><strong>${esc(propertyName(i.property_id))}</strong><div class="inspection-due">Due ${esc(i.next_due)}</div></div>${isStaff()?btn('Start inspection','new-inspection',i.property_id,true):''}</div>`).join('')||empty('No inspections due in the next 3 days.')}</div>`;
 if(page==='inspections')return head('Inspection reports','Published reports are shared with the correct family.',isStaff()?btn('Start inspection','new-inspection','',true):'')+`<div class="panel">${inspectionRows(filtered(data.inspections))}</div>`;
 if(page==='requests')return head('Service requests','Track requests and their assigned work.',btn('Request service','new-request','',true))+`<div class="panel">${filtered(data.requests).sort((a,b)=>({Urgent:0,High:1,Normal:2,Low:3}[a.priority||'Normal']-({Urgent:0,High:1,Normal:2,Low:3}[b.priority||'Normal'])||a.created_at.localeCompare(b.created_at))).map(r=>`<div class="row"><div><strong>${esc(r.title)}</strong><div class="muted">${esc(propertyName(r.property_id))}</div><p>${esc(r.description)}</p>${isStaff()&&r.status!=='completed'?btn('Link work order','link-request',r.id)+(!r.work_order_id?btn('Create work order','request-work',r.id):''):''}</div><div class="actions">${requestPriorityBadge(r.priority)}${badge(r.status)}${data.user.role==='admin'?btn('Edit priority','request-priority',r.id):''}</div></div>`).join('')||empty('No service requests yet.')}</div>`;
 if(page==='arrivals'){const pending=data.arrivals.filter(a=>!['ready','completed','cancelled'].includes(a.status)),ready=data.arrivals.filter(a=>['ready','completed'].includes(a.status));if(activeArrival){const a=data.arrivals.find(a=>a.id===activeArrival);if(a)return arrivalDetail(a);}const rows=arrivalFilter==='ready'?ready:pending;return head('Arrival preparation','Review submitted arrivals, shopping, rooms and notes.',btn('Plan arrival','new-arrival','',true))+`<div class="tabs"><button data-action="arrival-filter" data-id="pending" class="${arrivalFilter==='pending'?'active':''}">Needs confirmation (${pending.length})</button><button data-action="arrival-filter" data-id="ready" class="${arrivalFilter==='ready'?'active':''}">Ready (${ready.length})</button></div>`+arrivalCards(rows);}
 if(page==='maintenance')return head('Preventive maintenance','Generate each due visit once from its schedule.',`<div class="actions">${btn('Run due schedules','run-maintenance','',true)}${btn('Add schedule','new-maintenance')}</div>`)+`<div class="panel">${filtered(data.maintenance).map(m=>`<div class="row ${isOverdue(m.next_due)?'overdue-item':''}"><div><strong>${esc(m.title)}</strong><div class="muted">${esc(propertyName(m.property_id))} · ${esc(m.frequency)} · Due ${esc(m.next_due)}</div></div>${btn('Create due work','generate-maintenance',m.id)}</div>`).join('')||empty('No maintenance schedules yet.')}</div>`;
 if(page==='assets')return head('Assets & equipment','Equipment identity, warranty details and service history.',btn('Add asset','new-asset','',true))+assetRows2(filtered(data.assets));
 if(page==='documents')return head('Documents','Uploaded files stay attached to their residence.',isStaff()?btn('Upload document','new-document','',true):'')+`<div class="panel">${fileRows(filtered(data.files.filter(f=>!f.inspection_id&&!f.work_order_id)))}</div>`;
 if(page==='calendar'){const events=[...data.work.filter(w=>w.due_date).map(w=>({title:w.title,date:w.due_date,property_id:w.property_id,status:w.status})),...data.arrivals.map(a=>({title:'Arrival preparation',date:a.arrival_at,property_id:a.property_id,status:a.status})),...data.inspections.map(i=>({title:'Property inspection',date:i.inspection_date,property_id:i.property_id,status:i.status}))].sort((a,b)=>a.date.localeCompare(b.date));return head('Calendar','Scheduled work, inspections and arrivals.')+`<div class="panel">${events.map(e=>`<div class="row ${isOverdue(e.date,e.status)?'overdue-item':''}"><div><strong>${esc(e.title)}</strong><div class="muted">${esc(propertyName(e.property_id))} · ${esc(e.date.replace('T',' '))}</div></div>${badge(e.status)}</div>`).join('')||empty('No scheduled events yet.')}</div>`;}
 if(page==='billing')return billingView();if(page==='users')return usersView();
 if(page==='audit')return head('Audit history','Recorded account and operational changes.')+`<div class="panel">${data.audit.map(a=>`<div class="row"><div><strong>${esc(label(a.action.replaceAll('.',' ')))}</strong><div class="muted">${esc(a.actor_name)} · ${esc(new Date(a.created_at).toLocaleString())}</div></div></div>`).join('')||empty('No activity recorded.')}</div>`;
 if(page==='notifications')return head('Notifications')+`<div class="panel">${data.notifications.map(n=>`<div class="row"><div><strong>${esc(n.title)}</strong><div class="muted">${esc(new Date(n.created_at).toLocaleString())}</div></div>${!n.read_at?btn('Mark read','read-notification',n.id):badge('read')}</div>`).join('')||empty('You are up to date.')}</div>`;
 if(page==='staff'&&data.user.role==='admin')return staffView();if(page==='staff-schedules'&&isStaff())return scheduleView();if(page==='routes')return routeView();return '';
}
function profileView(){const u=data.user;return head('My profile','Manage your contact details and account security.')+`<div class="two"><section class="panel"><h2>Personal details</h2><p><strong>Name</strong><br>${esc(u.name)}</p><p><strong>Phone</strong><br>${esc(u.phone||'Not entered')}</p><p><strong>Preferred contact</strong><br>${esc(u.preferred_contact||'No preference')}</p>${btn('Edit details','edit-profile','',true)}</section><section class="panel"><h2>Sign-in & security</h2><p class="muted">Account ID: ${esc(u.id)}</p><p><strong>Email</strong><br>${esc(u.email)}</p><p><strong>Role</strong><br>${esc(label(u.role))}</p><div class="actions">${btn('Change password','profile-password')}${btn('Change email','profile-email')}</div></section></div>${mfaPanel()}`;}
function workRows(rows){return rows.map(w=>`<details class="work-card ${isOverdue(w.due_date,w.status)?'overdue-item':''}"><summary><span class="work-card-heading"><strong>${esc(w.title)}</strong><div class="muted">${esc(w.property_name||propertyName(w.property_id))}${w.due_date?' · Due '+esc(w.due_date):''}</div></span>${isOverdue(w.due_date,w.status)?badge('overdue'):''}${badge(w.status)}</summary><div class="work-card-body">${assignmentSummary(w)}${data.user.role==='vendor'?`<p class="work-manager">Residence manager: <strong>${esc(data.properties.find(p=>p.id===w.property_id)?.account_manager_name||'Not assigned')}</strong></p>`:''}${w.description?`<p class="pre">${esc(w.description)}</p>`:''}${w.service_notes?`<p class="pre">${esc(w.service_notes)}</p>`:''}<div class="actions">${data.user.role!=='client'?btn('Add note','work-note',w.id)+btn('Request more information','work-question',w.id):''}${data.user.role==='admin'?btn('Assign / schedule','work-assignment',w.id)+btn('Request client approval','request-estimate',w.id):''}${['open','scheduled'].includes(w.status)&&data.user.role!=='client'?btn('Start work','work-start',w.id):''}${['open','scheduled','in_progress'].includes(w.status)&&data.user.role!=='client'?btn('Add photo','work-photo',w.id)+btn('Submit completion','work-submit',w.id):''}${w.status==='submitted'&&isStaff()?btn('Accept completion','work-accept',w.id,true)+btn('Return to vendor','work-return',w.id):''}${data.files.filter(f=>f.work_order_id===w.id).map(f=>`<a class="button" href="/api/files/${f.id}" target="_blank" rel="noopener">${f.source_inspection_id?'Inspection evidence':'View photo'}</a>`).join('')}</div>${workUpdates(w)}</div></details>`).join('')||empty('No work orders in this view.');}
function requestPriorityField(value='normal'){return select('priority','Priority','<option value="low" '+(value==='low'?'selected':'')+'>Low</option><option value="normal" '+(value==='normal'?'selected':'')+'>Normal</option><option value="high" '+(value==='high'?'selected':'')+'>High</option><option value="urgent" '+(value==='urgent'?'selected':'')+'>Urgent</option>');}
function clientView(c){const homes=data.properties.filter(p=>p.client_id===c.id);return head(c.name||'Family','Family details',btn('Back to families','navigate','clients'))+'<div class="panel"><h2>'+esc(c.name||'Family')+'</h2><p class="muted">'+esc(c.email||'No email')+(c.phone?' · '+esc(c.phone):'')+'</p><h3>Residences</h3>'+homes.map(p=>'<div class="row"><div><strong>'+esc(p.name)+'</strong><div class="muted">'+esc(p.address||'Address not entered')+'</div></div>'+btn('View residence','property',p.id)+'</div>').join('')+'</div>';}
function inspectionEmailMessage(status){if(status==='sent')return 'Report email sent.';if(status==='failed')return 'Report email could not be sent.';if(status==='skipped')return 'No report email was sent.';return 'Report email status: '+label(status||'pending')+'.';}
function inspectionRecipient(p){const recipient=p?.inspection_report_email||p?.inspection_email||p?.report_email||p?.manager_email||p?.account_manager_email||'';return '<div class="inspection-recipient"><strong>Inspection report recipient</strong><p class="muted">'+esc(recipient||'No recipient saved')+'</p>'+btn('Edit email','inspection-recipient-edit',p.id)+'</div>';}
function inspectionRows(rows){return rows.map(i=>`<div class="row ${i.status==='draft'&&isOverdue(i.inspection_date,i.status)?'overdue-item':''}"><div><strong>${esc(propertyName(i.property_id))}</strong><div class="muted">${esc(i.inspection_date)} · ${esc(i.frequency||'One-time')}${i.next_due?' · Next due '+esc(i.next_due):''} · ${data.files.filter(f=>f.inspection_id===i.id).length} photos</div></div><div class="actions">${badge(i.status)}${btn(i.status==='draft'?'Continue':'View report','inspection',i.id)}${i.status==='draft'&&isStaff()?btn('Delete draft','inspection-delete',i.id):''}${i.status==='published'?`<a class="button" href="/api/inspections/${i.id}/pdf">Download PDF</a>`:''}</div></div>`).join('')||empty('No inspection reports yet.');}
function fileRows(rows){return rows.map(f=>`<div class="row"><div><strong>${esc(f.name)}</strong><div class="muted">${esc(propertyName(f.property_id))} · ${Math.ceil(f.bytes/1024)} KB</div></div><a class="button" href="/api/files/${f.id}" target="_blank" rel="noopener">Open</a></div>`).join('')||empty('No files uploaded.');}
function assetRows(rows){return `<div class="grid">${rows.map(a=>`<div class="card"><div class="eyebrow">${esc(a.category)}</div><h2>${esc(a.name)}</h2><p class="muted">${esc(propertyName(a.property_id))} · ${esc(a.location)}</p><p>Model: ${esc(a.model||'Not recorded')}<br>Serial: ${esc(a.serial||'Not recorded')}<br>Warranty: ${esc(a.warranty||'Not recorded')}</p>${isStaff()?btn('Create work order','asset-work',a.id):''}<h3 class="summary">Service history</h3>${data.work.filter(w=>w.asset_id===a.id&&w.status==='completed').map(w=>`<div class="row"><div><strong>${esc(w.title)}</strong><div class="muted">${esc(w.service_notes)}</div></div></div>`).join('')||'<p class="muted">No completed services recorded.</p>'}</div>`).join('')}</div>`+(rows.length?'':empty('No assets recorded.'));}
function arrivalCards(rows){return rows.map(a=>`<button class="card arrival-card" data-action="arrival-open" data-id="${a.id}" type="button"><div class="eyebrow">${esc(propertyName(a.property_id))}</div><h2>${esc(a.arrival_at.replace('T',' '))}</h2><p class="muted">${esc(a.needs||'No additional notes')}</p><div class="actions"><span class="badge">${a.room_status?.filter(r=>r.ready).length||0}/${a.room_status?.length||0} rooms ready</span><span class="badge">${a.items?.filter(i=>['purchased','stocked'].includes(i.status)).length||0}/${a.items?.length||0} items stocked</span></div></button>`).join('')||empty('No arrivals in this section.');}
function arrivalDetail(a){return btn('Back to arrivals','arrival-back')+`<div class="hero summary"><div class="eyebrow">${esc(propertyName(a.property_id))}</div><h1>Arrival preparation</h1><div class="muted">${esc(a.arrival_at.replace('T',' '))}</div>${badge(a.status)}</div><div class="two"><div class="panel"><h2>Notes</h2><p class="pre">${esc(a.needs||'No additional notes.')}</p></div><div class="panel"><h2>Shopping items</h2>${a.items?.map(i=>`<div class="row ${['purchased','stocked'].includes(i.status)?'item-stocked':''}"><div><strong>${esc(i.name)} · ${esc(i.quantity)}</strong><div class="muted">${esc(i.notes||'')}</div></div>${isStaff()?`<div class="actions"><label class="check-row"><input type="checkbox" data-arrival="${a.id}" data-item="${i.id}" data-item-field="purchased" ${['purchased','stocked'].includes(i.status)?'checked':''}> Purchased</label><label class="check-row"><input type="checkbox" data-arrival="${a.id}" data-item="${i.id}" data-item-field="substitutionNeeded" ${i.substitutionNeeded?'checked':''}> Substitution needed</label><input class="substitution-input" aria-label="What was purchased instead" data-arrival="${a.id}" data-item="${i.id}" data-item-field="substitution" value="${esc(i.substitution||'')}" placeholder="What was purchased instead?"></div>`:badge(i.status)}</div>`).join('')||empty('No shopping items selected.')}</div></div><div class="panel summary"><h2>Rooms</h2>${a.room_status?.map(r=>`<div class="row room-readiness ${r.ready?'room-ready':''}">${roomDetails(r)}${isStaff()?`<label class="check-row"><input type="checkbox" data-arrival="${a.id}" data-room-key="${esc(r.key)}" data-room-field="ready" ${r.ready?'checked':''}> Ready</label>`:r.ready?badge('ready'):badge('open')}</div>`).join('')||empty('No rooms configured.')}</div><div class="actions summary">${isStaff()&&!['ready','completed','cancelled'].includes(a.status)?btn('Confirm preparation is ready','arrival-ready',a.id,true):''}</div>`;}
function arrivalRows(rows){return rows.map(a=>`<div class="panel"><div class="row"><div><h3>${esc(propertyName(a.property_id))}</h3><div class="muted">Arrival ${esc(a.arrival_at.replace('T',' '))}</div></div>${badge(a.status)}</div><p class="pre">${esc(a.needs||'No additional needs requested.')}</p>${a.room_status?.length?`<h3 class="summary">Room readiness</h3>${a.room_status.map(r=>`<div class="row room-readiness ${r.ready?'room-ready':''}">${roomDetails(r)}${isStaff()?`<label class="check-row"><input type="checkbox" data-arrival="${a.id}" data-room-key="${esc(r.key)}" data-room-field="ready" ${r.ready?'checked':''}> Ready</label>`:r.ready?badge('ready'):badge('open')}</div>`).join('')}`:''}${a.items.map(i=>`<div class="row ${i.status==='stocked'?'item-stocked':''}"><div><strong>${esc(i.name)} · ${esc(i.quantity)}</strong><div class="muted">${esc(i.notes)}</div></div>${isStaff()?`<div class="actions"><label class="check-row"><input type="checkbox" data-arrival="${a.id}" data-item="${i.id}" data-item-field="purchased" ${['purchased','stocked'].includes(i.status)?'checked':''}> Purchased</label><label class="check-row"><input type="checkbox" data-arrival="${a.id}" data-item="${i.id}" data-item-field="substitutionNeeded" ${i.substitutionNeeded?'checked':''}> Substitution needed</label><input class="substitution-input" aria-label="What was purchased instead" data-arrival="${a.id}" data-item="${i.id}" data-item-field="substitution" value="${esc(i.substitution||'')}" placeholder="What was purchased instead?"></div>`:badge(i.status)}</div>`).join('')}<div class="actions summary">${isStaff()&&!['ready','completed','cancelled'].includes(a.status)?btn('Confirm preparation is ready','arrival-ready',a.id,true):''}</div></div>`).join('')||empty('No arrivals planned.');}
function residenceView(){const p=data.properties.find(p=>p.id===propertyId);if(!p)return empty('Residence not available.');let tabs=['overview','inspections','shopping','arrivals','services','documents','assets'];if(data.user.role==='admin')tabs.push('off_site_butler');if(isStaff())tabs.push('access_codes','manual','notes');if(data.user.role==='vendor')tabs=['services'];let html=btn('Back to residences','navigate','properties')+`<div class="hero summary"><div class="eyebrow">${esc(p.client_name||'Residence')}</div><h1>${esc(p.name)}</h1><p><strong>Residence Manager:</strong> ${esc(p.account_manager_name||'Not assigned')}</p><div class="muted">${esc(p.address)}</div><div class="actions">${data.user.role==='admin'?btn('Edit address','edit-property',p.id)+btn('Archive residence','archive-property',p.id):data.user.role==='client'?btn('Plan my arrival','new-arrival',p.id,true):''}</div></div><div class="tabs">${tabs.map(t=>`<button data-action="tab" data-id="${t}" class="${t===tab?'active':''}">${t==='access_codes'?'Access & codes':t==='off_site_butler'?'Residence Manager':esc(label(t))}</button>`).join('')}</div>`;
 if(tab==='off_site_butler'&&data.user.role==='admin')html+=`<div class="panel"><h2>Residence Manager</h2><p>${esc(p.account_manager_name||'Not assigned')}</p>${btn('Select Residence Manager','assign-butler',p.id,true)}</div>`;
 if(tab==='overview'){const upcomingWork=data.work.filter(w=>w.property_id===p.id&&w.status!=='completed');const latestInspections=data.inspections.filter(i=>i.property_id===p.id).sort((a,b)=>(b.inspection_date||'').localeCompare(a.inspection_date||'')).slice(0,1);html+=`<div class="two residence-overview-panels"><details class="panel collapsible-panel"><summary>Upcoming work (${upcomingWork.length})</summary><div class="collapsible-content">${workRows(upcomingWork)}</div></details><details class="panel collapsible-panel"><summary>Latest inspections (${latestInspections.length})</summary><div class="collapsible-content">${inspectionRows(latestInspections)}</div></details></div>`;}
 if(tab==='family'||tab==='overview'){let profile={};try{profile=JSON.parse(p.client_profile||'{}');}catch{}const members=profile.members||[];html+=`<div class="panel"><div class="head"><div><h2>Family members and guests</h2><p class="muted">Quick access for everyone associated with this residence.</p></div>${['admin','client'].includes(data.user.role)?btn('Add member or guest','residence-member',p.id,true):''}</div>${members.map(m=>`<div class="row"><div><strong>${esc([m.firstName,m.lastName].filter(Boolean).join(' '))}</strong><div class="muted">${esc(m.relationship||'Family member')}${m.email?' · '+esc(m.email):''}${m.phone?' · '+esc(m.phone):''}${m.preferredContact?' · Preferred: '+esc(m.preferredContact):''}</div></div>${familyMemberActions(p,m)}</div>`).join('')||empty('No family members or guests have been added yet.')}</div>`;}
 if(tab==='inspections')html+=`<div class="panel">${isStaff()?inspectionRecipient(p):''}${(()=>{const due=data.inspections.filter(i=>i.property_id===p.id&&i.next_due).sort((a,b)=>a.next_due.localeCompare(b.next_due))[0];return due?`<div class="notice inspection-due ${isOverdue(due.next_due)?'overdue-item':''}"><strong>Next inspection due: ${esc(due.next_due)}</strong> ${isStaff()?btn('Edit schedule','edit-inspection-schedule',due.id):''}</div>`:''})()}${isStaff()?btn('Start inspection','new-inspection',p.id,true):''}${inspectionRows(data.inspections.filter(i=>i.property_id===p.id))}</div>`;
 if(tab==='shopping')html+=`<div class="panel"><div class="head"><h3>Preferred shopping list</h3><div class="actions">${btn('Add item','new-shopping',p.id,true)}${btn('Import CSV / TXT','shopping-import',p.id)}</div></div>${data.shopping.filter(i=>i.property_id===p.id).map(i=>`<div class="row"><div><strong>${esc(i.name)}</strong><div class="muted">${esc(i.category)} · ${esc(i.notes)}</div></div><div class="actions"><b>${esc(i.quantity)}</b>${btn('Edit','edit-shopping',i.id)}${btn('Remove','remove-shopping',i.id)}</div></div>`).join('')||empty('Add this residence’s preferred groceries and household items.')}${btn('Plan an arrival','new-arrival',p.id)}</div>`;
 if(tab==='arrivals')html+=btn('Plan arrival','new-arrival',p.id,true)+arrivalRows(data.arrivals.filter(a=>a.property_id===p.id));
 if(tab==='services')html+=`<div class="panel">${isStaff()?btn('New work order','new-work',p.id,true):data.user.role==='client'?btn('Request service','new-request',p.id,true):''}${workRows(data.work.filter(w=>w.property_id===p.id))}</div>`;
 if(tab==='documents')html+=`<div class="panel">${isStaff()?btn('Upload document','new-document',p.id,true):''}${fileRows(data.files.filter(f=>f.property_id===p.id&&!f.inspection_id&&!f.work_order_id))}</div>`;
 if(tab==='assets')html+=(isStaff()?btn('Add asset','new-asset',p.id,true):'')+assetRows2(data.assets.filter(a=>a.property_id===p.id));
 if(tab==='access_codes'&&isStaff())html+=`<div class="panel"><h2>Access & codes</h2><p>Gate, door, alarm and lockbox details. Available to administrators and the assigned Residence Manager. Viewing and changes are recorded.</p>${btn('View access details','access-codes',p.id,true)}</div>`;
 if(tab==='manual')html+=`<div class="panel"><h3>House manual</h3><p class="muted">Operational procedures for authorized staff. Store gate codes, door codes and alarm credentials in Access & codes.</p><div class="pre">${esc(p.manual||'No procedures recorded yet.')}</div>${btn('Edit manual','edit-manual',p.id)}</div>`;
 if(tab==='notes')html+=`<div class="panel">${btn('Add internal note','new-note',p.id,true)}${data.notes.filter(n=>n.property_id===p.id).map(n=>`<div class="row"><div class="pre">${esc(n.body)}</div><span class="muted">${esc(n.created_at.slice(0,10))}</span></div>`).join('')}</div>`;
 return html;
}
function inspectionView(){const i=data.inspections.find(i=>i.id===activeInspection);if(!i)return empty('Inspection unavailable.');const published=i.status==='published';return head(propertyName(i.property_id),`${i.inspection_date} · ${published?'Published inspection report':'Inspection in progress'}`,btn('Back to reports','navigate','inspections'))+`<div class="panel"><div class="company-report-brand">${companyLogo()}<strong>${esc(data.company)}</strong></div><div class="report-title"><div class="actions">${badge(i.status)}${published?`<a class="button primary" href="/api/inspections/${i.id}/pdf">Download PDF report</a>`:''}</div></div><div class="muted">Inspected by: ${esc(i.inspector_name||'Not recorded')}${i.published_at?' · Completed: '+esc(new Date(i.published_at).toLocaleString('en-US',{timeZone:'America/New_York',timeZoneName:'short'})):''}</div>${isStaff()?`<div class="panel">${published?`<strong>Report email</strong><p>${esc(i.report_email||'No recipient saved')}</p><p>${esc(inspectionEmailMessage(i.email_status))}</p>${data.user.role==='admin'&&i.report_email&&i.email_status!=='sent'?btn('Retry report email','inspection-email',i.id):''}`:inspectionRecipient(data.properties.find(p=>p.id===i.property_id))}</div>`:''}${followupPanel(i)}${!published?`<div id="draft-status" class="draft-status" role="status">Draft autosave is on.</div>`:''}<h2>Walkthrough checklist</h2>${i.answers.map(a=>`<div class="inspection-item" style="${a.status==='monitor'?'background:#fff3bc;border-left:4px solid #c49116;padding:16px':a.status==='attention'?'background:#ffe0e0;border-left:4px solid #b82635;padding:16px':''}"><div><div class="eyebrow">${esc(a.section)}</div><strong>${esc(a.label)}</strong></div>${published?badge(a.status):`<select aria-label="Result for ${esc(a.label)}" data-answer="${a.key}">${['unchecked','pass','monitor','attention','na'].map(s=>`<option value="${s}" ${s===a.status?'selected':''}>${s==='na'?'Not applicable':label(s)}</option>`).join('')}</select>`}${published?`<span class="muted">${esc(a.note)}</span>`:`<input aria-label="Notes for ${esc(a.label)}" data-answer-note="${a.key}" value="${esc(a.note)}" placeholder="Reading, observation or N/A reason">`}</div>`).join('')}${published?`<h2>Notes to the client</h2><p class="pre">${esc(i.notes)}</p>`:textarea('notes','Notes to the client',i.notes)+textarea('internalNotes','Internal notes — not shared in reports',i.internal_notes)}${published?`<h2>Inspection summary</h2><p class="pre">${esc(i.summary)}</p>`:textarea('summary','Inspection summary',i.summary)}<h2>Photo evidence</h2><div class="photo-grid">${data.files.filter(f=>f.inspection_id===i.id).map(f=>`<a href="/api/files/${f.id}" target="_blank" rel="noopener"><img src="/api/files/${f.id}" alt="${esc(f.name)}"></a>`).join('')}</div>${!published?`<div class="actions">${btn('Add photos','inspection-photo',i.id)}${btn('Save draft','inspection-save',i.id,true)+btn('Delete draft','inspection-delete',i.id)}<details><summary>Draft recovery</summary>${btn('Download local draft','draft-export',i.id)}${btn('Use server draft','draft-discard',i.id)}</details>${data.user.role==='admin'?btn('Complete & publish','inspection-publish',i.id,true):''}</div><p class="muted">Changes save automatically. If your connection drops, keep this tab open: your checklist and notes remain here until they sync. Photo uploads and publishing require a connection.</p>`:''}</div>`;}
function billingView(){const total=data.invoices.reduce((n,i)=>n+i.amount_minor,0),paid=data.invoices.reduce((n,i)=>n+i.paid_minor,0);return head('Billing','Admin-only invoices and payment records.',btn('Create invoice','new-invoice','',true))+`<div class="stats"><div class="stat">Invoiced<b>${money(total)}</b></div><div class="stat">Collected<b>${money(paid)}</b></div><div class="stat">Outstanding<b>${money(total-paid)}</b></div></div><div class="panel table-wrap"><table><thead><tr><th>Invoice</th><th>Client</th><th>Amount</th><th>Balance</th><th>Due</th><th></th></tr></thead><tbody>${data.invoices.map(i=>`<tr><td><b>${esc(i.number)}</b><div class="muted">${esc(i.description)}</div></td><td>${esc(i.client_name)}</td><td>${money(i.amount_minor)}</td><td>${money(i.amount_minor-i.paid_minor)}</td><td>${esc(i.due_date)}</td><td>${i.paid_minor<i.amount_minor?btn('Record payment','new-payment',i.id):badge('paid')}</td></tr>`).join('')}</tbody></table>${!data.invoices.length?empty('No invoices yet.'):''}</div>`;}
function usersView(){return head('Team & access','Each person uses their own login. Invitations expire after 48 hours.',btn('Invite someone','new-invite','',true))+`<div class="panel"><h3>Accounts</h3>${data.users.map(u=>`<div class="row"><div><strong>${esc(u.name)}</strong><div class="muted">${esc(u.email)} · ${esc(label(u.role))}${!u.active?' · Suspended':''}</div></div><div class="actions">${u.role==='employee'?btn('Assign residence','grant-access',u.id):''}${u.id!==data.user.id&&u.active?btn('Suspend access','suspend-user',u.id):''}</div></div>`).join('')}</div>`+invitationHistoryView();}
let routePlannerSelections=null;
function routeWorkIds(){return new Set(data.work.filter(w=>!['completed','cancelled'].includes(w.status)).map(w=>w.property_id));}
function routeSelected(id){const state=routePlannerSelections;if(state.manual.has(id))return state.manual.get(id);return state.inspections&&upcomingInspections().some(i=>i.property_id===id)||state.work&&routeWorkIds().has(id);}
function routeView(){routePlannerSelections={inspections:true,work:false,manual:new Map()};return head('Plan your day','Choose groups of residences or select individual stops below.')+`<div class="panel route-planner"><div class="route-address">${input('origin','Starting address','text','',false)}<button type="button" id="routeLocate">Locate me</button></div><div id="routeOriginStatus" role="status" aria-live="polite"></div><div id="routeOriginResults" class="address-suggestions"></div><small>Address search by Photon · OpenStreetMap</small><h3 class="summary">Add to route</h3><label class="check-row"><input type="checkbox" data-route-group="inspections" checked> Add inspections due in the next 3 days</label><label class="check-row"><input type="checkbox" data-route-group="work"> Add open work orders</label><p class="muted">You can also add or remove individual residences below. Each residence appears once in your route.</p><h3>Select residences for this route</h3>${data.properties.map(p=>`<label class="check-row"><input type="checkbox" class="route-stop" value="${esc(p.id)}" ${routeSelected(p.id)?'checked':''}><span><b>${esc(p.name)}</b><br><span class="muted">${esc(p.address||'Add an address before navigation')}${upcomingInspections().filter(i=>i.property_id===p.id).map(i=>' · Inspection due: '+esc(i.next_due)).join('')}${routeWorkIds().has(p.id)?' · Open work orders':''}</span></span></label>`).join('')||empty('No residences assigned.')}${btn('Open Google Maps directions','navigate-route','',true)}</div>`;}
document.addEventListener('change',event=>{const el=event.target;if(!routePlannerSelections)return;if(el.dataset.routeGroup){routePlannerSelections[el.dataset.routeGroup]=el.checked;document.querySelectorAll('.route-stop').forEach(stop=>{stop.checked=!!routeSelected(stop.value);});}else if(el.classList.contains('route-stop'))routePlannerSelections.manual.set(el.value,el.checked);});

const residenceSelect=selected=>select('propertyId','Residence',option(data.properties,'id','name',selected||propertyId));
function createForm(title,fields,endpoint,extra={},after){dialog(title,fields,'Save',async(b,form)=>{if(form.querySelector('[name="guestIds"]'))b.guestIds=[...form.querySelectorAll('[name="guestIds"]:checked')].map(el=>el.value);const result=await api(endpoint,{...b,...extra});if(after)after(result);toast('Saved.');});}
function arrivalGuestFields(p){let profile={};try{profile=JSON.parse(p.client_profile||'{}');}catch{}const members=Array.isArray(profile.members)?profile.members:[];return '<b>Family and guests joining</b>'+ (members.length?members.map(m=>`<label class="check-row"><input type="checkbox" name="guestIds" value="${esc(m.id)}"><span>${esc([m.firstName,m.lastName].filter(Boolean).join(' ')||'Guest')}<small>${esc(m.relationship||'Guest')}</small></span></label>`).join(''):'<p class="muted">No family members or guests are saved for this residence yet. Add them from the residence overview.</p>');}
function wireResidenceForm(){wireRooms();syncRoomProfile();document.querySelectorAll('[name=roomKey],#f-bedrooms,#f-fullBathrooms,#f-halfBathrooms').forEach(el=>el.addEventListener('change',syncRoomProfile));const search=$('f-addressSearch'),suggestions=$('addressSuggestions');if(!search||!suggestions)return;let timer;search.addEventListener('input',()=>{clearTimeout(timer);const q=search.value.trim();if(q.length<3){suggestions.innerHTML='';return;}timer=setTimeout(async()=>{try{const body=await fetch('/api/geocode/autocomplete?q='+encodeURIComponent(q)).then(r=>r.json());const rows=body.features||[];suggestions.innerHTML=rows.map((row,i)=>`<button type="button" class="address-suggestion" data-address-index="${i}">${esc(row.properties?.formatted||'')}</button>`).join('');suggestions.querySelectorAll('[data-address-index]').forEach((el,i)=>el.onclick=()=>{const a=rows[i].properties||{};$('f-streetAddress').value=[a.housenumber,a.street].filter(Boolean).join(' ')||a.formatted||'';$('f-city').value=a.city||a.town||a.village||'';$('f-state').value=a.state||'';$('f-postalCode').value=a.postcode||'';$('f-country').value=a.country||'United States';search.value=a.formatted||'';suggestions.innerHTML='';});}catch{suggestions.innerHTML='<span class="muted">Address lookup unavailable; enter the fields manually.</span>'; }},350);});}

async function saveInspection(){return syncInspectionDraft();}
async function jpeg(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Choose a JPEG, PNG or WebP photo. Convert HEIC photos first.');if(file.size>10*1024*1024)throw Error('Choose a photo smaller than 10 MB.');const bitmap=await createImageBitmap(file,{imageOrientation:'from-image'});const scale=Math.min(1,2000/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();return canvas.toDataURL('image/jpeg',.85).split(',')[1];}
function uploadForm(title,prop,inspectionId=null,workId=null){dialog(title,`${prop?'':residenceSelect()}<div class="field full"><label for="upload">${inspectionId||workId?'Photos':'JPEG photo or PDF document'}</label><input id="upload" type="file" accept="${inspectionId||workId?'image/jpeg,image/png,image/webp':'application/pdf,image/jpeg,image/png,image/webp'}" ${inspectionId||workId?'multiple':''} required></div>${!inspectionId&&!workId?select('visibility','Who can see this document?','<option value="internal">Staff only</option><option value="client">Staff and this family</option>'):''}`,'Upload',async(b,form)=>{const files=[...form.querySelector('#upload').files];if(files.length>10)throw Error('Upload at most 10 photos at a time.');for(const file of files){if(file.size>10*1024*1024)throw Error('Maximum size is 10 MB per file.');let base64;if(file.type==='application/pdf'){const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let pos=0;pos<bytes.length;pos+=8192)binary+=String.fromCharCode(...bytes.subarray(pos,pos+8192));base64=btoa(binary);}else base64=await jpeg(file);await api('files',{propertyId:prop||b.propertyId,inspectionId,workId,name:file.type==='application/pdf'?file.name:file.name.replace(/\.[^.]+$/,'')+'.jpg',base64,visibility:b.visibility});}toast('Files uploaded.');});}
function parseCsv(text){const rows=[];let row=[],field='',quoted=false;for(let n=0;n<text.length;n++){const c=text[n];if(c==='"'){if(quoted&&text[n+1]==='"'){field+='"';n++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(field.trim());field='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[n+1]==='\n')n++;row.push(field.trim());if(row.some(Boolean))rows.push(row);row=[];field='';}else field+=c;}if(quoted)throw Error('CSV contains an unclosed quotation mark.');row.push(field.trim());if(row.some(Boolean))rows.push(row);return rows;}
