document.addEventListener('change',async event=>{const el=event.target;if(!el.dataset.arrival)return;const a=data.arrivals.find(a=>a.id===el.dataset.arrival);try{const payload={id:a.id,version:a.version};if(el.dataset.item){const field=el.dataset.itemField;if(field==='substitutionNeeded')Object.assign(payload,{itemId:el.dataset.item,substitutionNeeded:el.checked,substitution:el.closest('.actions')?.querySelector('[data-item-field=\"substitution\"]')?.value||''});else if(field==='substitution')Object.assign(payload,{itemId:el.dataset.item,substitutionNeeded:el.closest('.actions')?.querySelector('[data-item-field=\"substitutionNeeded\"]')?.checked||false,substitution:el.value});else Object.assign(payload,{itemId:el.dataset.item,itemStatus:el.checked?'purchased':'requested'});}if(el.dataset.roomKey)Object.assign(payload,{roomKey:el.dataset.roomKey,roomReady:el.checked});await api('arrivals/update',payload);await load();toast(el.dataset.roomKey?'Room readiness saved.':el.dataset.itemField==='substitutionNeeded'||el.dataset.itemField==='substitution'?'Substitution details saved.':'Purchase status saved.');}catch(error){toast(error.message);await load();}});
async function boot(){try{const workspaceToken=new URLSearchParams(location.search).get('workspaceInvite');if(workspaceToken){await workspaceRegistration(workspaceToken);return;}const status=await api('status');const invitation=new URLSearchParams(location.search).get('invite');if(status.user&&!invitation)await load();else portalAuth(status.configured,invitation);}catch(error){$('app').innerHTML=`<div class="loading"><h1>EstateAegis could not connect</h1><p>${esc(error.message)}</p><p>Keep the EstateAegis server running, then refresh this page.</p></div>`;}}
boot();
function assetInspectionView(){const a=data.assets.find(a=>a.id===activeAssetInspection);if(!a)return empty('Asset unavailable.');const report=data.asset_inspections.filter(i=>i.asset_id===a.id).sort((x,y)=>y.inspection_date.localeCompare(x.inspection_date))[0];const items=['Exterior, hull or body condition','Tires, trailer or running gear','Engine, battery or power system','Fuel, oil, coolant or fluid levels','Safety equipment and required gear','Leaks, damage or warning indicators','Storage, cover and security'];if(assetInspectionReadOnly&&report)return head(`${a.name} inspection`,`${report.inspection_date} · Completed asset inspection`,btn('Back to assets','navigate','assets'))+`<div class="panel"><div class="actions"><a class="button primary" href="/api/asset-inspections/${report.id}/pdf">Download PDF</a></div>${report.answers.map(x=>`<div class="row"><div><strong>${esc(x.label)}</strong>${x.note?`<div class="muted">${esc(x.note)}</div>`:''}</div>${badge(x.status)}</div>`).join('')}<h3 class="summary">Overall notes</h3><p class="pre">${esc(report.notes||'No overall notes recorded.')}</p></div>`;return head(`${a.name} inspection`,`Record a focused inspection for this ${a.category||'asset'}.`,btn('Back to assets','navigate','assets'))+`<div class="panel asset-inspection-page"><p class="muted">Review each item that applies and record anything needing follow-up.</p><div class="field"><label for="asset-date">Inspection date</label><input id="asset-date" type="date" value="${today()}"></div>${items.map((label,i)=>`<div class="inspection-item"><div><strong>${esc(label)}</strong><div class="muted">Choose the result and add an observation if needed.</div></div><select id="asset-check-${i}"><option value="pass">Pass</option><option value="attention">Needs attention</option><option value="na">Not applicable</option></select><input id="asset-note-${i}" placeholder="Observation or follow-up note"></div>`).join('')}<div class="field full"><label for="asset-inspection-notes">Overall notes</label><textarea id="asset-inspection-notes" placeholder="Summarize the condition or work needed"></textarea></div><div class="actions">${btn('Save inspection','asset-inspection-save','',true)}</div></div>`;}
function assetRows2(rows){return `<div class="grid">${rows.map(a=>{const last=data.asset_inspections.filter(i=>i.asset_id===a.id).sort((x,y)=>y.inspection_date.localeCompare(x.inspection_date))[0];return `<div class="card"><div class="eyebrow">${esc(a.category)}</div><h2>${esc(a.name)}</h2><p class="muted">${esc(propertyName(a.property_id))} · ${esc(a.location||'Location not recorded')}</p><p>Model: ${esc(a.model||'Not recorded')}<br>Serial: ${esc(a.serial||'Not recorded')}<br>Warranty: ${esc(a.warranty||'Not recorded')}<br>Mileage: ${esc(a.mileage||'Not recorded')}<br>Hours: ${esc(a.hours||'Not recorded')}</p>${a.notes?`<p class="pre">${esc(a.notes)}</p>`:''}${isStaff()?btn('Edit asset','edit-asset',a.id)+btn(`${a.name} inspection`,'asset-inspection',a.id)+btn('Create work order','asset-work',a.id):''}<h3 class="summary">${esc(a.name)} inspection</h3>${last?`<div class="row"><div><strong>Last checked</strong><div class="muted">${esc(last.inspection_date)}</div></div>${btn('View inspection','asset-inspection-view',a.id)}</div>`:'<p class="muted">No asset inspections recorded.</p>'}<h3 class="summary">Service history</h3>${data.work.filter(w=>w.asset_id===a.id&&w.status==='completed').map(w=>`<div class="row"><div><strong>${esc(w.title)}</strong><div class="muted">${esc(w.service_notes)}</div></div></div>`).join('')||'<p class="muted">No completed services recorded.</p>'}</div>`}).join('')}</div>`+(rows.length?'':empty('No assets recorded.'));}
let routeAddressTimer,routeAddressRequest,routeAddressRevision=0;
document.addEventListener('input',event=>{
 const field=event.target;if(field.id!=='f-origin')return;
 const revision=++routeAddressRevision;clearTimeout(routeAddressTimer);routeAddressRequest?.abort();
 const results=$('routeOriginResults'),status=$('routeOriginStatus');if(!results)return;
 results.replaceChildren();status.textContent='';const q=field.value.trim();if(q.length<3)return;
 routeAddressTimer=setTimeout(async()=>{
  const controller=new AbortController();routeAddressRequest=controller;
  status.textContent='Finding addresses…';
  try{
   const response=await fetch('/api/geocode/autocomplete?q='+encodeURIComponent(q),{signal:controller.signal});
   if(!response.ok)throw Error('Lookup failed');
   const body=await response.json();if(revision!==routeAddressRevision||!field.isConnected)return;
   for(const feature of body.features||[]){
    const p=feature.properties||{};
    const address=[p.name,[p.housenumber,p.street].filter(Boolean).join(' '),p.city||p.town||p.village,p.state,p.postcode,p.country].filter(Boolean).join(', ');
    if(!address)continue;
    const button=document.createElement('button');button.type='button';button.className='address-suggestion';button.textContent=address;
    button.onclick=()=>{++routeAddressRevision;field.value=address;results.replaceChildren();status.textContent='Starting address selected.';field.focus();};
    results.appendChild(button);
   }
   status.textContent=results.children.length?'Select an address below.':'No matches. You can enter the address manually.';
  }catch(error){if(error.name!=='AbortError'&&revision===routeAddressRevision)status.textContent='Address search unavailable. Enter your address manually.';}
 },500);
});
document.addEventListener('click',async event=>{
 if(event.target.id!=='routeLocate')return;
 const button=event.target,field=$('f-origin'),status=$('routeOriginStatus');
 ++routeAddressRevision;clearTimeout(routeAddressTimer);routeAddressRequest?.abort();$('routeOriginResults').replaceChildren();
 if(!navigator.geolocation){status.textContent='Location is unavailable on this device. Enter an address manually.';return;}
 const revision=routeAddressRevision;button.disabled=true;status.textContent='Finding your location…';
 try{
  const position=await new Promise((resolve,reject)=>navigator.geolocation.getCurrentPosition(resolve,reject,{enableHighAccuracy:true,timeout:15000,maximumAge:60000}));
  if(!field.isConnected||revision!==routeAddressRevision)return;
  const lat=position.coords.latitude,lon=position.coords.longitude;
  try{const response=await fetch(`/api/geocode/reverse?lat=${lat}&lon=${lon}`,{signal:AbortSignal.timeout(8000)});const body=await response.json();const p=body.features?.[0]?.properties||{};const address=p.formatted||[p.name,[p.housenumber,p.street].filter(Boolean).join(' '),p.city||p.town||p.village,p.state,p.postcode,p.country].filter(Boolean).join(', ');field.value=address||`${lat.toFixed(6)},${lon.toFixed(6)}`;status.textContent=address?'Current address found.':'Current location selected.';}catch{field.value=`${lat.toFixed(6)},${lon.toFixed(6)}`;status.textContent='Location selected. Coordinates will be used as your starting point.';}
 }catch(error){if(field.isConnected&&revision===routeAddressRevision)status.textContent=error.code===1?'Location permission denied. Allow location access or enter an address manually.':'Could not find your location. Try again or enter an address manually.';}
 finally{button.disabled=false;}
});
function globalSearch(){const q=search.trim().toLowerCase();if(!q)return view();const match=v=>Object.values(v||{}).some(x=>typeof x==='string'&&x.toLowerCase().includes(q));const props=data.properties.filter(match),jobs=data.work.filter(match);return head('Search results',`Matches for “${esc(search)}”`)+`<div class="panel"><h2>Residences</h2>${props.map(p=>`<div class="row"><strong>${esc(p.name)}</strong>${btn('View residence','property',p.id)}</div>`).join('')||empty('No matching residences.')}</div><div class="panel"><h2>Work orders</h2>${workRows(jobs)||empty('No matching work orders.')}</div>`;}
window.addEventListener('focus',()=>{if(data&&page!=='inspection'&&!$('modal').open&&Date.now()-lastLoadAt>1500)load().catch(error=>toast(error.message));});
if(document.modelContext?.registerTool){
 const lifecycle=new AbortController();
 Promise.resolve(document.modelContext.registerTool({name:'open_estateos_inspection',title:'Open inspection report',description:'Open an inspection already accessible to the signed-in account. Does not publish or modify records.',inputSchema:{type:'object',properties:{inspectionId:{type:'string'}},required:['inspectionId'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},async execute(input){if(!input||typeof input.inspectionId!=='string'||Object.keys(input).length!==1)throw Error('Provide an inspectionId.');await load();const report=data.inspections.find(i=>i.id===input.inspectionId);if(!report)throw Error('Inspection unavailable to this account.');activeInspection=report.id;page='inspection';render();return {id:report.id,status:report.status};}},{signal:lifecycle.signal})).catch(()=>{});
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}


function portalAuth(configured,invitation){let portal=invitation?'client':'admin';let formMode=configured?'login':'setup',forgot=false,reset=new URLSearchParams(location.search).has('reset'),resetToken=new URLSearchParams(location.search).get('reset')||'';const portalInfo={client:['Client portal','View residences, arrivals, shopping, requests and reports.'],admin:['Admin portal',configured?'Manage your EstateAegis workspace.':'Create and manage the EstateAegis workspace.'],vendor:['Vendor portal','View assigned jobs, upload evidence and track completion.']};const draw=()=>{const info=portalInfo[portal],isSetup=portal==='admin'&&!configured&&formMode==='setup',isRecovery=portal==='admin'&&(forgot||reset);const fields=reset?input('token','Reset token','hidden',resetToken,false)+input('newPassword','New password','password')+input('confirmPassword','Confirm new password','password'):forgot?input('email','Email','email'):invitation?input('name','Your name')+(input('email','Invited email','email')):(isSetup?input('company','Company name')+logoField()+input('setupKey','Setup key from Render','password','',false)+input('name','Your name'):input('email','Email','email'))+input('password','Password','password')+input('code','Authenticator or recovery code (if enabled)','text','',false);$('app').innerHTML=`<div class="auth"><section class="auth-intro"><video class="auth-video" autoplay muted loop playsinline preload="metadata" poster="/waterfront.jpg" aria-hidden="true"><source src="/waterfront.mp4" type="video/mp4"></video><div class="brand"><img class="ea-brand-icon" src="/ea-shield.png" alt="" width="40" height="40">EstateAegis</div><h1>Your residences.<br>Our team.<br>One place.</h1><p>The smarter way to manage private residences.</p></section><section class="auth-form"><div><div class="eyebrow">${isRecovery?'Password recovery':'EstateAegis access'}</div><h2>${reset?'Set a new password':forgot?'Forgot your password?':esc(info[0])}</h2><p class="muted">${reset?'Choose a new password for your account.':forgot?'Enter your email and we will send a secure reset link if an account matches.':esc(info[1])}</p>${!isRecovery?`<div class="portal-tiles">${Object.entries(portalInfo).map(([key,value])=>`<button type="button" class="portal-tile ${portal===key?'selected':''}" data-portal="${key}"><strong>${key==='client'?'Client':key==='admin'?'Admin':'Vendor'}</strong><span>${esc(value[1])}</span></button>`).join('')}</div>`:''}<div id="authError" class="error" hidden></div><form id="authForm">${fields}<button class="primary" type="submit">${reset?'Reset password':forgot?'Send reset link':isSetup?'Create company':'Log in'}</button></form>${isRecovery?'<p class="footer-note"><button type="button" class="link-button" data-back>Back to sign in</button></p>':isSetup?'<p class="footer-note">Admin setup is for the person running the workspace.</p>':'<p class="footer-note">Use the portal assigned to your account. Ask the administrator for an invitation if you need access.</p>'+(portal==='admin'?'<p class="footer-note"><button type="button" class="link-button" data-forgot>Forgot password?</button></p>':'')}</div></section></div>`;document.querySelectorAll('[data-portal]').forEach(button=>button.onclick=()=>{portal=button.dataset.portal;formMode=portal==='admin'&&!configured?'setup':'login';draw();});const back=document.querySelector('[data-back]');if(back)back.onclick=()=>{forgot=false;reset=false;history.replaceState(null,'','/login');draw();};const fb=document.querySelector('[data-forgot]');if(fb)fb.onclick=()=>{forgot=true;draw();};$('authForm').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const payload=Object.fromEntries(new FormData(e.target));if(e.target.querySelector('[name=companyLogo]'))payload.logoData=await readCompanyLogo(e.target);if(invitation)payload.token=invitation;if(reset){await api('password-reset',payload);reset=false;forgot=false;history.replaceState(null,'','/login');draw();$('authError').textContent='Your password was reset. You can now sign in.';$('authError').hidden=false;}else if(forgot){await api('password-reset/request',payload);$('authError').textContent='If an account matches, we’ll send a reset link.';$('authError').hidden=false;e.target.reset();}else{await api(invitation?'accept-invite':isSetup?'setup':'login',isSetup?payload:{...payload,role:portal});history.replaceState(null,'','/');await load();}}catch(error){$('authError').textContent=error.message;$('authError').hidden=false;}finally{e.submitter.disabled=false;}};};draw();}
